-- migrate:no-transaction
-- Step 2 of 4 for orders.public_id: backfill existing rows.
--
-- The procedure walks the primary key in ranges of batch_size ids and commits after each range,
-- so every UPDATE holds row locks on at most batch_size orders, and only for the length of one batch.
-- Rows inserted during the backfill already get a value from the column default (set in 0004).
-- Re-running is safe: only rows that are still NULL are touched.
SET lock_timeout = '3s';

CREATE OR REPLACE PROCEDURE orders_backfill_public_id(batch_size bigint)
LANGUAGE plpgsql
AS $$
DECLARE
  last_id bigint := 0;
  max_id bigint;
BEGIN
  SELECT max(id) INTO max_id FROM orders;
  WHILE last_id < coalesce(max_id, 0) LOOP
    UPDATE orders
       SET public_id = gen_random_uuid()
     WHERE id > last_id AND id <= last_id + batch_size AND public_id IS NULL;
    last_id := last_id + batch_size;
    COMMIT;
  END LOOP;
END
$$;

CALL orders_backfill_public_id(5000);

DROP PROCEDURE orders_backfill_public_id(bigint);

