-- migrate:no-transaction
-- Step 4 of 4 for orders.public_id: NOT NULL.
--
-- SET NOT NULL on its own scans all of orders while holding ACCESS EXCLUSIVE. Instead:
--   1. add a CHECK (public_id IS NOT NULL) as NOT VALID (catalog-only, brief lock);
--   2. VALIDATE it (scans, but only SHARE UPDATE EXCLUSIVE, so reads and writes continue);
--   3. SET NOT NULL, which Postgres 12+ accepts without a scan because the validated CHECK proves it;
--   4. drop the helper CHECK.
-- If the backfill missed any row, step 2 fails and nothing is changed.
SET lock_timeout = '3s';

ALTER TABLE orders DROP CONSTRAINT IF EXISTS orders_public_id_not_null;

ALTER TABLE orders
  ADD CONSTRAINT orders_public_id_not_null CHECK (public_id IS NOT NULL) NOT VALID;

ALTER TABLE orders VALIDATE CONSTRAINT orders_public_id_not_null;

ALTER TABLE orders ALTER COLUMN public_id SET NOT NULL;

ALTER TABLE orders DROP CONSTRAINT orders_public_id_not_null;

